-- BOOK-INGEST-AUDIT.md F56: the forty totem animals Spirit West prints on
-- printed 96-105, one row each in `totems` (migration 056), and the nine
-- O.C.C.s that pick one given the `totem` key that makes the pick real.
--
-- WHAT A ROW HOLDS. `skills` is the totem's own list in catalog spelling,
-- with the bonus the book prints; printed 96 gives +10% INSTEAD where the
-- O.C.C. already has the skill, and composeClass does that, so it is not
-- written here. `bonuses` is the human-form "Bonuses:" line in the class
-- grammar - dice and S.D.C. pools included, since a totem's apply at creation
-- the way a class's do. `bonus_note` is what that grammar cannot hold.
-- `powers` is the Totem Warrior's giant-form paragraph, condensed; only a
-- class whose key says `powers: true` shows it. `description` paraphrases
-- the traits.
--
-- FORTY, NOT FORTY-EIGHT. The survey and F56 both said 48, from a count taken
-- before the cache was read in column order. The book's "Totem Animal
-- Descriptions" run Alligator to Wolf, forty headings; Crow/Raven's traits sit
-- after Dog on printed 99 because of the two-column layout, and are one entry.
--
-- READ FROM THE INK, 2026-09-10. Crawfish's shell M.D.C. is +1D4x10+10: the
-- cache prints "+104x10+10", and PDF page 100 renders "1D4". Whale's dive depth
-- is printed "1000 feet (205 m)" in the ink as well - the book's own slip, as
-- 1000 ft is about 305 m - and is stored as printed with that said.
--
-- SKILL NAMES, where the book's word is not the catalog's: Athletics is
-- Athletics (general); Body Building is Body Building & Weight Lifting; herd
-- cattle is Herding Cattle; cooking is Cook; imitate voices is Imitate Voices &
-- Sounds; sculpting/whittling is Whittling & Sculpting; tracking is Tracking
-- (people), the row for the skill Rifts calls Tracking; Owl's "lore:
-- magic/geomancy and lines of power" is Lore: Magic, noted on the entry;
-- Rattlesnake's paired handguns and quickdraw are W.P. Paired Weapons and W.P.
-- Quick Draw, noted on each. Every name is asserted to exist below.
--
-- SAVES. "Save vs magic" is spell_magic and ritual_magic both, as 44 of the 73
-- classes with a spell-magic save write it. Crow/Raven's "psionics or magical
-- mind control" is +3 vs psionics plus a labelled +3 vs magical mind control;
-- Opossum's paralysis save is labelled, as F7's saves.other is for.

INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('alligator', 'Alligator', '[{"name":"Swimming","bonus":10},{"name":"Detect Ambush"},{"name":"Camouflage"},{"name":"Wrestling"}]', '{"attributes":{"PE":1,"ME":1},"pools":{"sdc":20},"saves":{"coma_death_pct":5}}', NULL, '+6 P.S., +20+1D4x10 M.D.C. Locking jaws bite for 5D6 M.D. and need P.S. 24 or more to pry open; tail strikes do supernatural P.S. damage +1D6 M.D. Holds breath one minute per P.E. point, and swims, dives and prowls underwater at 50% +5% per level, swimming at double land speed. Once every 15 minutes a two-melee burst adds +10 to Spd. Horror Factor 12.', 'A patient, powerful swamp hunter who waits in ambush and strikes in sudden bursts. Includes crocodiles, komodo dragons and other large reptiles.', 'Rifts World Book 15: Spirit West p.96');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('badger', 'Badger', '[{"name":"Athletics (general)"},{"name":"Detect Concealment","bonus":5}]', '{"attributes":{"PE":1,"Spd":2},"combat":{"dodge":1,"roll":1,"pull_punch":1}}', NULL, '+2 P.S., +2 P.P. Bite 3D6 M.D., claws add 1D6 M.D. to supernatural P.S. damage, nightvision 200 ft (61 m). Digs through earth at 5 ft (1.5 m) per melee round without leaving a passage, or a hole at 1 ft (0.3 m) per round; a tunnel that does leave a passage goes 2 ft (0.6 m) per minute.', 'A small digging predator: confident, energetic and tenacious, who stands his ground for what he values.', 'Rifts World Book 15: Spirit West p.96-97');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('bat', 'Bat', '[{"name":"Land Navigation","bonus":10},{"name":"Detect Ambush","bonus":5},{"name":"Intelligence"}]', '{"attributes":{"Spd":4},"combat":{"initiative":2,"dodge":1}}', 'Rarely surprised: enemies prowl against the character at -20%.', '+1 I.Q., +2 M.E., +1 P.P., +1D4x10 to flying speed. Bite 1D6 M.D.; flying claw strikes do supernatural P.S. damage. Radar/sonar lets him sense his surroundings in total darkness or when blind and locates invisible foes, but not intangible ones such as ghosts, illusions or holograms. Horror Factor 13.', 'A keenly aware night flyer who keeps his deepest thoughts hidden; sociable, but chafes in regimented settings.', 'Rifts World Book 15: Spirit West p.97');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('bear', 'Bear', '[{"name":"Body Building & Weight Lifting"},{"name":"Climbing"},{"name":"Wrestling"}]', '{"attributes":{"PE":1,"PS":"1d4"},"pools":{"sdc":15},"saves":{"horror_factor":2}}', NULL, '+8 P.S., +2 P.E., +30 physical M.D.C. Bite 4D6 M.D., claws add 3D6 M.D. to supernatural P.S. damage. Heightened hearing and smell: +1 initiative, track by smell 50% +5% per level, recognize a known scent 40% +4% per level. Horror Factor 14.', 'Large, powerful and usually quiet, even lazy, but fiercely protective of his own and savage when provoked.', 'Rifts World Book 15: Spirit West p.97');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('beaver', 'Beaver', '[{"name":"Swimming","bonus":15},{"name":"Carpentry"},{"name":"Whittling & Sculpting"}]', NULL, '+2 to dodge in water; fatigues at half the normal rate; +5% to any skill or labor involving construction or repair; a human-form bite does 1D6 S.D.C.', '+1 M.E., +2 P.S. Bite 2D4 M.D.; holds breath one minute per P.E. point; chews through non-metal S.D.C. materials such as wood, rope and plastic at about an inch per minute, but not M.D.C. materials. Good hearing, water-resistant fur and an excellent swimmer: +1 initiative and +2 dodge underwater.', 'An industrious builder and loyal companion, steadfast on a narrow task but apt to lose sight of the bigger picture.', 'Rifts World Book 15: Spirit West p.97');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('blue-jay', 'Blue-Jay', '[{"name":"Land Navigation","bonus":10},{"name":"Escape Artist"},{"name":"Palming"}]', '{"attributes":{"IQ":1,"PS":1,"PB":"1d4"},"combat":{"strike":1}}', NULL, '+1 P.S., +5 P.B., +1 strike, +2 dodge. Beak strike 1D6 M.D., supernatural P.S., and flies at up to 60 mph (96.5 km).', 'Smart, bold and beautiful, but a boastful trickster who puts himself first and dodges the blame.', 'Rifts World Book 15: Spirit West p.97');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('boar', 'Boar', '[{"name":"Running"},{"name":"Body Building & Weight Lifting"}]', '{"attributes":{"PS":2},"combat":{"strike":1,"parry":1,"dodge":1,"roll":2}}', NULL, '+2 P.S., +1 P.P., +2 P.E., +6 Spd, +10 M.D.C. Tusks add 1D6 M.D. to supernatural P.S. damage. Track by smell 35% +5% per level, recognize scents 25% +5% per level. Horror Factor 11.', 'Tough, quick and short-tempered: aggressive, uncouth and relentless in a fight. Includes pigs, wild swine and tapirs.', 'Rifts World Book 15: Spirit West p.98');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('bobcat', 'Bobcat', '[{"name":"Climbing","bonus":10},{"name":"Prowl","bonus":5},{"name":"Hunting"}]', '{"attributes":{"ME":1,"PP":1},"combat":{"initiative":1,"dodge":1}}', NULL, '+1 I.Q., +2 P.P. Retractable claws add 2D4 M.D. to supernatural P.S. damage, nightvision 500 ft (152 m), leaps 15 ft (4.6 m) high or across, and +10% to Climbing.', 'A small, quick and cunning wildcat and a brooding loner who prefers the wilderness. Includes the lynx and other small wildcats.', 'Rifts World Book 15: Spirit West p.98');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('buffalo', 'Buffalo', '[{"name":"Wilderness Survival","bonus":10},{"name":"Skin & Prepare Animal Hides","bonus":5},{"name":"Land Navigation"}]', '{"attributes":{"PS":3},"pools":{"sdc":20},"combat":{"damage_bonus":2}}', NULL, '+4 P.E., +8 P.S., +1D4x10 physical M.D.C. A horn gore or smash does supernatural P.S. +3D6 M.D.; a running horn ram does supernatural P.S. +4D6 M.D. and uses two attacks. Acute hearing and a good sense of smell: +1 initiative, +1 dodge. An aura of awe equal to Horror Factor 15.', 'A strong, hardy provider and protector at peace with his place, a compassionate team player, and revered above nearly all others by the Plains tribes. Includes bison, yaks and other large herd animals.', 'Rifts World Book 15: Spirit West p.98');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('bull', 'Bull', '[{"name":"Body Building & Weight Lifting"},{"name":"Herding Cattle","bonus":5}]', '{"attributes":{"PS":2,"Spd":6},"pools":{"sdc":12},"combat":{"initiative":1},"saves":{"horror_factor":2}}', NULL, '+2 P.E., +6 P.S., +3 save vs Horror Factor, +5D6 physical M.D.C. A horn gore or smash does supernatural P.S. +2D6 M.D.; a running ram does 5D6 M.D. plus supernatural P.S. damage and counts as two attacks.', 'Strength, power and charisma: a brave fighter who hates lies and charges into battle headlong. Includes the ox and other bovine work animals.', 'Rifts World Book 15: Spirit West p.98');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('coyote', 'Coyote', '[{"name":"Disguise","bonus":10},{"name":"Imitate Voices & Sounds","bonus":5},{"name":"Ventriloquism","bonus":5},{"name":"Cardsharp","bonus":10}]', '{"attributes":{"IQ":1,"MA":1},"combat":{"initiative":1,"dodge":2}}', NULL, '+3 M.A., +1 P.P., +4 Spd. Claws add 1D4 M.D. to supernatural P.S. damage, bite 2D6 M.D., track by smell 50% +5% per level, recognize specific scents 40% +5% per level.', 'The great trickster and con man, and sometimes the hero: curious, bold and charismatic, and suited to unprincipled and anarchist characters.', 'Rifts World Book 15: Spirit West p.98-99');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('crawfish', 'Crawfish (Crayfish)', '[{"name":"Fishing","bonus":10},{"name":"W.P. Paired Weapons"}]', '{"attributes":{"PE":2},"pools":{"sdc":10},"saves":{"horror_factor":3}}', NULL, '+3 M.E., +3 P.S., +3 Spd, +1D4x10+10 physical M.D.C. (shell). Immune to Horror Factor; claws add 2D6 M.D. to supernatural P.S. damage; antennae act as motion detectors (Rifts RPG p.230) for +1 dodge and +1 initiative, and blindness penalties are halved. Horror Factor 12.', 'An armored and courageous warrior who gives and asks no quarter and waits patiently for a foe to err. Includes crabs, lobsters and other crustaceans.', 'Rifts World Book 15: Spirit West p.99');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('crow-raven', 'Crow/Raven', '[{"name":"Seduction","bonus":10},{"name":"Cook","bonus":10},{"name":"Escape Artist","bonus":10},{"name":"Streetwise","bonus":5}]', '{"attributes":{"IQ":2,"MA":2,"Spd":2},"saves":{"psionics":3,"other":[{"label":"vs magical mind control","bonus":3}]}}', NULL, '+4 M.E., +2 dodge in flight, +3 save vs psionics or magical mind control. Beak or peck 1D6 M.D., claws add +4 M.D. to supernatural P.S., and flies at up to 80 mph (128.7 km).', 'A clever, cunning trickster and fast-talking opportunist who loves his pleasures and can survive almost anywhere. Includes ravens and minks.', 'Rifts World Book 15: Spirit West p.99');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('deer', 'Deer', '[{"name":"Running"},{"name":"Detect Ambush","bonus":5}]', '{"attributes":{"Spd":6},"combat":{"initiative":1,"dodge":2}}', NULL, '+2 P.S., +1 P.E., +20 Spd. An antler gore adds 1D6 to supernatural P.S. damage, and ramming adds 2D6 and uses only one attack; leaps 8 ft (2.4 m) high or 12 ft (3.6 m) across; keen hearing. +4 initiative with defensive moves (dodge, duck, leap, flee, hide), +1 parry, +2 dodge.', 'Gentle, passive and friendly but wary; prefers flight to fighting and, like Buffalo, is respected for giving himself so that man survives.', 'Rifts World Book 15: Spirit West p.99');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('dog', 'Dog', '[{"name":"Running"},{"name":"Herding Cattle"},{"name":"Breed Dogs"}]', '{"attributes":{"IQ":1,"MA":2,"ME":2},"saves":{"horror_factor":2}}', NULL, '+2 P.S., +2 P.E., +2 P.P. Bite 2D6 M.D., claws add 1D6 to supernatural P.S. damage, swims 50%, runs 35 mph (56 km), track by smell 60% +5% per level, recognize scents 50% +5% per level.', 'Man''s long companion: a loyal guardian, a brave ally and a merciful defender to the end. Includes all domesticated dogs.', 'Rifts World Book 15: Spirit West p.99');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('dolphin', 'Dolphin', '[{"name":"Swimming","bonus":20},{"name":"Sing"}]', '{"attributes":{"IQ":1,"ME":1,"MA":2}}', '+2 to dodge underwater.', '+1 I.Q., +1 M.E., +2 M.A., +2 P.P., +20 Spd in water, +12 physical M.D.C. Bite 1D6+4 M.D., ram does supernatural P.S. damage, half damage from cold, holds breath P.E. x2 minutes. Sonar senses underwater surroundings even in total darkness and locates invisible foes, but not intangible ones.', 'A swift, playful and benevolent sea creature: intelligent, compassionate and loyal, and a reliable team player. Includes porpoises and killer whales.', 'Rifts World Book 15: Spirit West p.100');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('eagle', 'Eagle', '[{"name":"Fishing","bonus":10},{"name":"Hunting"}]', '{"attributes":{"PP":1,"Spd":3,"MA":1},"combat":{"strike":1}}', NULL, '+2 P.P., flies at up to 70 mph (112.6 km). Talons add 3D6 M.D. to supernatural P.S. damage, bite 4D6 M.D., and sees detail up to two miles (3.2 km) away. +2 initiative, +1 strike, +1 disarm, +2 dodge.', 'A large, majestic and greatly respected predator: proud, strong, and a swift, clean killer. Includes all eagles and condors.', 'Rifts World Book 15: Spirit West p.100');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('ferret', 'Ferret', '[{"name":"Pick Pockets","bonus":10},{"name":"Climbing"}]', '{"attributes":{"PP":2,"Spd":2},"combat":{"dodge":1}}', NULL, '+2 P.P., +10 Spd. Claws add 1D4 to supernatural P.S. damage and +10% to Climbing, bite 2D6. A racing metabolism gives +2 strike and +2 attacks per melee, but he eats four times a normal person''s food (twice as much in human form).', 'Small, agile, inquisitive and secretive, fun-loving, and a collector of curious things nobody else has claimed. Includes weasels, ermine, sable, grison and marten.', 'Rifts World Book 15: Spirit West p.100');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('fox', 'Fox', '[{"name":"Escape Artist","bonus":5},{"name":"Pick Locks","bonus":5},{"name":"Palming"},{"name":"Trap/Mine Detection"}]', '{"attributes":{"IQ":1,"ME":2,"Spd":3},"combat":{"dodge":1}}', NULL, '+1 I.Q., +1 P.P., +6 Spd, supernatural P.S. Bite 2D6 M.D.; swims 50%, climbs 50%, runs 30 mph (48 km); track by smell 60% +5% per level, recognize scents 50% +5% per level.', 'The small, resourceful cousin of Wolf and Coyote: a sneaky deceiver and thief who avoids fights he cannot win, and often a symbol of wisdom.', 'Rifts World Book 15: Spirit West p.100');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('goat', 'Goat', '[{"name":"Wilderness Survival","bonus":10}]', '{"attributes":{"PE":2,"ME":1},"saves":{"toxins_poisons":1,"harmful_drugs":1,"spell_magic":1,"ritual_magic":1}}', NULL, '+2 I.Q., +8 P.E., +4 Spd. A horn ram adds 2D4 to supernatural P.S. damage. +5 save vs poison, +3 vs drugs, +3 vs magic, +2 vs psionics. Amplified hearing, as the cybernetic implant: +1 parry, +2 dodge, +6 initiative.', 'A tenacious, stubborn and territorial survivor of harsh climates and little food. Includes sheep.', 'Rifts World Book 15: Spirit West p.100-101');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('hawk-falcon', 'Hawk/Falcon', '[{"name":"Prowl","bonus":10},{"name":"Hunting"}]', '{"attributes":{"PP":1,"Spd":3},"combat":{"strike":1}}', NULL, '+2 initiative, +1 strike, +2 dodge, flies at up to 60 mph (96.5 km). Talons add 2D6 M.D. to supernatural P.S. damage, bite 3D6 M.D., and sees detail up to two miles (3.2 km) away.', 'A small, feisty and tenacious predator who strikes without warning and cares only for the kill; suits anarchist and evil characters. Includes hawks, falcons, buzzards and kites.', 'Rifts World Book 15: Spirit West p.101');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('horse', 'Horse', '[{"name":"Running"},{"name":"Horsemanship: Cowboy"}]', '{"attributes":{"PS":1,"Spd":"1d6"},"pools":{"sdc":10}}', 'Leaps one additional foot (0.3 m) for every four points of P.S.', '+5 P.S., +24 Spd, +12 physical M.D.C. Kicks add 2D6 M.D. to supernatural P.S. damage; acute hearing gives +1 initiative and +1 dodge.', 'Smart, swift and strong: a loyal, hard-working companion with a noble spirit that runs free.', 'Rifts World Book 15: Spirit West p.101');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('hummingbird', 'Hummingbird', '[{"name":"Running"},{"name":"Acrobatics","bonus":10}]', '{"attributes":{"Spd":6},"combat":{"dodge":2,"attacks":1}}', '+10% to pilot hovercycles, jets and other small, fast vehicles.', '+4 P.P., +50 flying Spd, +2 strike and +4 dodge in flight, and one more attack per melee in flight on top of the one above. Beak or claw attacks do 1D6 less than supernatural P.S. damage, never under 1D4 M.D. Eats four times a normal person''s food (twice as much in human form).', 'A tiny, fast and hot-headed bird who takes on foes far larger than himself; a symbol of war to South American tribes.', 'Rifts World Book 15: Spirit West p.101');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('mole', 'Mole', '[{"name":"Intelligence","bonus":10},{"name":"Find Contraband","bonus":6}]', '{"attributes":{"MA":2}}', NULL, '+5 P.E. Claws add 1D6 to supernatural P.S. damage; nightvision 300 ft (91.5 m), but light-sensitive eyes. Digs 5 ft (1.5 m) per melee round without a passage, a hole at 1 ft (0.3 m) per round, and a tunnel at 2 ft (0.6 m) per minute; excavates 10 cubic feet per half hour, which collapses in 2D4 days unless shored up. Track by smell 20% +5% per level, recognize scents 30% +5% per level, and blindness penalties are halved.', 'Quiet, observant and secretive, easily forgotten, and so he uncovers what others hide; the unassuming helper of the Hopi Twins and a favorite of Spider Woman.', 'Rifts World Book 15: Spirit West p.101');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('moose', 'Moose', '[{"name":"Boxing"},{"name":"Swimming","bonus":10}]', '{"attributes":{"PS":2,"PE":1},"combat":{"strike":1}}', NULL, '+7 P.S., +3 P.E., +4D6 physical M.D.C., +2 initiative, +1 strike and parry. An antler gore adds 2D6 to supernatural P.S. damage and a hind-leg kick adds 2D6 M.D.; acute hearing. Horror Factor 13.', 'A large, powerful and honorable warrior who fights valiantly for a higher cause and so wins even in defeat. Includes elk.', 'Rifts World Book 15: Spirit West p.102');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('mouse', 'Mouse', '[{"name":"Prowl","bonus":5},{"name":"Climbing"},{"name":"Preserve Food"}]', '{"attributes":{"PP":1,"Spd":2},"saves":{"toxins_poisons":1}}', NULL, '+1 I.Q., +2 P.P., +4 Spd. Does 1D6 less than supernatural P.S. damage; claws add +10% to Climbing; bite 1D6 M.D. Acute hearing: +1 initiative, +1 dodge. Digs 5 ft (1.5 m) per melee round without a passage, a hole at 1 ft (0.3 m) per round, and a tunnel at 2 ft (0.6 m) per minute.', 'Small, quiet, observant and crafty: a symbol of adaptability, fertility and survival. Includes rats, hamsters, groundhogs and other small rodents.', 'Rifts World Book 15: Spirit West p.102');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('opossum', 'Opossum', '[{"name":"Climbing","bonus":15},{"name":"Acrobatics"}]', '{"attributes":{"ME":1},"saves":{"horror_factor":3,"other":[{"label":"vs psionics or magic that paralyze or immobilize","bonus":2}]}}', NULL, '+2 M.E. Bite 1D6 M.D., claws add 2D4 M.D. to supernatural P.S. damage. A prehensile tail bears his weight, helps him climb and balance, and is +1 to parry with melee weapons. Nightvision 400 ft (122 m), track by smell 30% +5% per level, recognize scents 25% +5% per level, and feigns death as the psionic Death Trance at no I.S.P. cost.', 'Quiet, watchful and unobtrusive, but a savage fighter when cornered, and a fair actor who can bluff rage or play dead.', 'Rifts World Book 15: Spirit West p.102');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('otter', 'Otter', '[{"name":"Swimming","bonus":15}]', '{"attributes":{"IQ":1,"MA":2,"Spd":2}}', 'An excellent diver.', '+2 P.P., +6 Spd, +2 initiative, +1 dodge. Holds breath one minute per P.E. point; track by smell 45% +5% per level, recognize scents 45% +5% per level; whiskers sense vibration, so blindness penalties are halved.', 'Friendly, fun-loving and playful; a pacifist who helps anyone in need and escapes or ends a fight quickly.', 'Rifts World Book 15: Spirit West p.102');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('owl', 'Owl', '[{"name":"Streetwise","bonus":10},{"name":"Lore: Demons & Monsters","bonus":5},{"name":"Lore: Magic","note":"The book says lore of magic, geomancy and lines of power; the catalog holds it as Lore: Magic."}]', '{"attributes":{"IQ":1,"ME":1},"combat":{"initiative":1},"saves":{"spell_magic":1,"ritual_magic":1,"possession":2}}', NULL, '+2 M.E., +2 P.P., flies at 45 mph (72 km). Claws add 2D6 M.D. to supernatural P.S. damage; sees detail up to two miles (3.2 km) away, but nightvision is limited to 1,000 ft (300 m). Acute hearing and smell: +2 initiative, +1 dodge.', 'A totem of mystery and darkness but not of evil: the keeper of secrets and lost knowledge, who watches for bad medicine and knows when to leave dangerous things alone.', 'Rifts World Book 15: Spirit West p.102-103');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('porcupine', 'Porcupine', '[{"name":"Identify Plants & Fruit"}]', '{"attributes":{"ME":2,"PE":2},"combat":{"parry":2}}', NULL, '+15 physical M.D.C.; track by smell 30% +5% per level; excellent hearing. Quills do 2D6 (S.D.C. in normal animal form, M.D. as a giant) to anyone grabbing, grappling, punching or hitting him. Body slams or blocks do 5D6 M.D., and forearm strikes 2D6 M.D. plus supernatural P.S. damage.', 'Quiet and hard-headed, relying on his natural defenses in every situation; arguments roll off him, and he attacks only when an opening appears.', 'Rifts World Book 15: Spirit West p.103');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('puma-mountain-lion', 'Puma/Mountain Lion', '[{"name":"Hunting"},{"name":"Tracking (people)","bonus":5,"note":"The book says tracking; the catalog row for that skill is Tracking (people)."},{"name":"Climbing"}]', '{"attributes":{"PP":2,"PS":1,"Spd":2}}', NULL, '+4 P.S., +6 Spd, +2 initiative, +2 pull punch, +1 parry, +1 roll with impact, +1 attack per melee. Claws add 3D4 to supernatural P.S. damage, bite 3D6 M.D.; track by smell 40% +5% per level, recognize scents 35% +5% per level; keen hearing, and nightvision 200 ft (60 m).', 'A large, agile apex hunter, confident yet cautious and cool under fire. Also called cougar, panther and mountain lion.', 'Rifts World Book 15: Spirit West p.103');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('rabbit', 'Rabbit', '[{"name":"Running"},{"name":"Detect Ambush","bonus":5}]', '{"attributes":{"Spd":"1d6"},"combat":{"initiative":2,"dodge":1}}', NULL, '+4 P.P., +15 Spd, +2 initiative, +1 parry, +2 dodge. Leaps one foot per P.S. point up and two feet per point across; heightened smell and hearing. Leap Kick and Jump Kick (Rifts RPG p.35) cost him only two attacks, and kicks add 2D6 to supernatural P.S. damage.', 'Swift, alert and wary among strangers, gregarious and relaxed among friends, and values freedom above all. Includes rabbits and hares.', 'Rifts World Book 15: Spirit West p.103');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('raccoon', 'Raccoon', '[{"name":"Intelligence","bonus":10},{"name":"Cardsharp"}]', '{"attributes":{"IQ":2,"ME":2,"MA":2}}', NULL, '+4 M.A., +3 save vs illusions, +1 initiative, climbs 80%/60%, swims 65%, nightvision 600 ft (183 m), supernatural P.S. Articulated paws let him use skills in animal form, which most totem forms cannot.', 'Very intelligent, adaptable and crafty; loves a battle of wits, but underestimates his opponents and takes foolish risks.', 'Rifts World Book 15: Spirit West p.103');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('rattlesnake', 'Rattlesnake', '[{"name":"W.P. Paired Weapons","note":"The book pairs handguns, or a knife."},{"name":"W.P. Quick Draw","note":"Revolvers and pistols, the same as the Gunslinger O.C.C. (New West p.93)."}]', '{"attributes":{"PP":2,"ME":2},"combat":{"initiative":1}}', 'A natural Gunslinger or Gunfighter; a character of either O.C.C. does not take these skills and bonuses twice.', '+1 attack per melee, +2 P.P., +4 save vs poisons, drugs and toxins, +5 save vs Horror Factor, +10 physical M.D.C. Prowl 68%, climb 70%/60%, swim 60%, nightvision 400 ft (122 m), thermal sense to 100 ft (30.5 m). Every other round a darting strike adds +4 initiative, +2 strike and +1D6 bite damage, but counts as two attacks. Supernatural P.S.; a poison bite does 6D6 extra damage (save 14 or higher for half). Horror Factor 14.', 'The harbinger of death: a cold, silent, lightning-fast hunter who warns before he strikes and is dispassionate about death. Includes vipers and cobras.', 'Rifts World Book 15: Spirit West p.103');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('seal', 'Seal', '[{"name":"Swimming","bonus":15},{"name":"Fishing","bonus":5}]', '{"attributes":{"ME":1,"MA":1}}', '+1 to all combat rolls while in the water - strike, parry, dodge, roll, damage and the rest.', '+1 M.E., +2 P.P., +10 Spd swimming, +10 physical M.D.C. Immune to normal cold and freezing; supernatural or M.D. cold does half damage. Keen vision sees a 2 ft object clearly at 2 miles (3.2 km); holds breath one minute per two P.E. points.', 'Playful, fast and agile in water but awkward on land; excellent in a narrow field, and at his best in a team that covers his failings. Includes walruses, manatees and similar sea mammals.', 'Rifts World Book 15: Spirit West p.103-104');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('shark', 'Shark', '[{"name":"Swimming","bonus":10},{"name":"Tracking (people)","bonus":5,"note":"The book says tracking; the catalog row for that skill is Tracking (people)."}]', '{"attributes":{"PS":2,"PE":2},"combat":{"strike":1},"saves":{"horror_factor":2}}', NULL, '+4 P.S., +2 P.E., +20 physical M.D.C. Bite 6D6 M.D., tail swipe 2D6 plus supernatural P.S. damage; tracks prey by blood scent in water at 70% +5% per level and smells faint blood up to two miles (3.2 km) away. Horror Factor 15. When hit by a critical strike, on making a kill, or on any attack that damages his hit points, he must save vs insanity or fall into a blood frenzy like the Crazies'' Frenzy (Rifts RPG p.58), with 30 M.D.C. in place of the 30 S.D.C. and +1 strike and parry.', 'The silent, deadly hunter of the sea and a warrior''s totem, prone to blood frenzy and dangerous even to friends. Includes barracuda, piranha and other predatory fish.', 'Rifts World Book 15: Spirit West p.104');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('snake', 'Snake', '[{"name":"Holistic Medicine","bonus":5},{"name":"Surveillance"},{"name":"Prowl"}]', '{"attributes":{"MA":1}}', '+5% to all skills involving medicine and healing.', '+1 P.P., +4 save vs disease, +2 save vs Horror Factor, supernatural P.S., +6 physical M.D.C. Prowl 60%, climb 70%/60%, swim 60%, nightvision 400 ft (122 m), thermal sense to 65 ft (19.2 m).', 'The messenger of the Deep Earth gods, who keeps secrets well and knows medicine and the paths to the spirit caves; sly, patient and a little distrusted. Includes all non-poisonous snakes.', 'Rifts World Book 15: Spirit West p.104');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('turtle', 'Turtle', '[{"name":"Swimming","bonus":5},{"name":"Fishing"}]', '{"attributes":{"MA":1,"ME":2},"pools":{"sdc":"2d6"}}', NULL, '+2 P.S., +50 M.D.C. (shell), supernatural P.S., and holds his breath one minute per P.E. point.', 'The provider and life-giver who brought the first earth up from the great sea; even-tempered and tolerant behind a hard shell, slow but steadfast.', 'Rifts World Book 15: Spirit West p.105');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('whale', 'Whale', '[{"name":"Swimming","bonus":15},{"name":"Sing","bonus":10}]', '{"attributes":{"IQ":1,"MA":2,"PS":5},"pools":{"sdc":15}}', NULL, '+2 M.E., +4 M.A., +16 P.S., +12 swimming Spd, +80 M.D.C. Dives to 1000 feet (the book prints 205 m; 1000 ft is about 305 m) and survives depths to 2 miles (3.2 km); holds breath two minutes per P.E. point. Bite 2D6 M.D., supernatural P.S.; half damage from magical cold and none from normal cold. Once per melee he can Sing, at -1 to attacks and to every combat bonus but saves, maintaining one of Befuddle, Calling, Fear, Repel Animals, Thunderclap, Trance or Words of Truth as a mage of his level for as long as he sings (at most one melee per P.E. point plus one per level). Four songs a day, plus one per level beyond two.', 'A giant, graceful singer of the seas and a noble, loyal protector, revered by sea-dependent tribes as Buffalo is on the Plains.', 'Rifts World Book 15: Spirit West p.105');
INSERT OR IGNORE INTO totems (slug, name, skills, bonuses, bonus_note, powers, description, source_book) VALUES ('wolf', 'Wolf', '[{"name":"Running"},{"name":"Hunting"},{"name":"Tracking (people)","bonus":10,"note":"The book says tracking; the catalog row for that skill is Tracking (people)."}]', '{"attributes":{"IQ":1,"MA":1},"saves":{"horror_factor":2}}', NULL, '+2 M.E., +2 M.A., +2 P.P., +2D6 M.D.C. Bite 4D6 M.D., claws add 2D6 to supernatural P.S. damage, swims 50%, runs 35 mph (56 km), track by smell 70% +5% per level, recognize scents 65% +5% per level. Horror Factor 12.', 'Noble and courageous, a protector of his pack with a head for group tactics, and the last to leave so the others can escape.', 'Rifts World Book 15: Spirit West p.105');

-- The nine classes. Each gets the key, one line, before special_abilities,
-- and the two sentences that said the pick was not stored are rewritten to
-- say what it is now. Guarded so a second run changes nothing.
UPDATE imported_classes
   SET markdown = replace(replace(replace(markdown,
         char(10) || 'special_abilities:' || char(10),
         char(10) || 'totem: { from: "animal" }' || char(10) || 'special_abilities:' || char(10)),
         'Not stored; see BOOK-INGEST-AUDIT.md F56.', 'Chosen in the wizard from the shared totems catalog; see BOOK-INGEST-AUDIT.md F56.'),
         'The totem pick is not stored; see BOOK-INGEST-AUDIT.md F56.', 'The totem pick is the class''s totem key, chosen from the shared totems catalog (BOOK-INGEST-AUDIT.md F56).'),
       updated_at = datetime('now')
 WHERE class_id = 'animal-shaman' AND instr(markdown, char(10) || 'totem:') = 0;
