SELECT 'forty totems' AS assertion, count(*) AS got, 40 AS want FROM totems;
SELECT 'every totem cites its printed page' AS assertion, count(*) AS got, 40 AS want
  FROM totems WHERE source_book LIKE 'Rifts World Book 15: Spirit West p.%';
SELECT 'every totem skill is a catalog skill' AS assertion, count(*) AS got, 0 AS want
  FROM totems, json_each(totems.skills) AS j
 WHERE NOT EXISTS (SELECT 1 FROM skills WHERE skills.name = json_extract(j.value, '$.name'));
SELECT 'nine live classes pick a totem' AS assertion, count(*) AS got, 9 AS want
  FROM imported_classes WHERE deleted_at IS NULL AND instr(markdown, char(10) || 'totem: { from: "animal"') > 0;
SELECT 'only the Totem Warrior sees the powers' AS assertion, count(*) AS got, 1 AS want
  FROM imported_classes WHERE instr(markdown, 'totem: { from: "animal", powers: true }') > 0 AND class_id = 'totem-warrior';
SELECT 'no class still says the pick is not stored' AS assertion, count(*) AS got, 0 AS want
  FROM imported_classes WHERE instr(markdown, 'not stored; see BOOK-INGEST-AUDIT.md F56') > 0
     OR instr(markdown, 'Not stored; see BOOK-INGEST-AUDIT.md F56') > 0;

